application.css:
* {
  box-sizing: border-box;
}

:root {
  color: #172033;
  background: #eef2f7;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  line-height: 1.5;
}

body {
  margin: 0;
}

.quiz-shell {
  width: min(100% - 2rem,  fiftyrem);
  max-width: 50rem;
  margin: 0 auto;
  padding: 2rem 0 3rem;
}

.page-header,
.question,
.result {
  background: #ffffff;
  border: 1px solid #cbd5e1;
  border-radius: 0.75rem;
  box-shadow: 0 0.25rem 1rem rgb(15 23 42 / 0.06);
}

.page-header {
  padding: 1.5rem;
  margin-bottom: 1rem;
}

.eyebrow {
  color: #2457a6;
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  margin: 0 0 0.25rem;
  text-transform: uppercase;
}

h1,
h2 {
  line-height: 1.2;
}

h1 {
  margin: 0;
  font-size: clamp(1.8rem, 5vw, 2.5rem);
}

.page-header p:last-child {
  margin-bottom: 0;
}

.questions {
  display: grid;
  gap: 1rem;
}

.question {
  padding: 1.25rem;
}

.question h2 {
  font-size: 1.1rem;
  margin: 0 0 1rem;
}

fieldset {
  border: 0;
  margin: 0;
  padding: 0;
}

.option {
  align-items: center;
  border: 1px solid #b8c4d4;
  border-radius: 0.5rem;
  cursor: pointer;
  display: flex;
  gap: 0.7rem;
  margin-top: 0.6rem;
  padding: 0.75rem;
}

.option:hover {
  background: #f1f6ff;
  border-color: #2457a6;
}

.option:has(input:checked) {
  background: #e8f0ff;
  border-color: #2457a6;
  box-shadow: inset 0 0 0 1px #2457a6;
}

input {
  accent-color: #2457a6;
  block-size: 1.1rem;
  inline-size: 1.1rem;
  flex: 0 0 auto;
}

button {
  background: #174a91;
  border: 0;
  border-radius: 0.5rem;
  color: #ffffff;
  cursor: pointer;
  font: inherit;
  font-weight: 700;
  margin-top: 1.25rem;
  padding: 0.8rem 1.2rem;
}

button:hover {
  background: #10366b;
}

button:focus-visible,
input:focus-visible {
  outline: 3px solid #f59e0b;
  outline-offset: 3px;
}

.form-message {
  color: #9b1c1c;
  font-weight: 600;
  margin: 1rem 0 0;
}

.result {
  margin-top: 1.5rem;
  padding: 1.25rem;
}

.result h2 {
  font-size: 1.15rem;
  margin: 0 0 0.4rem;
}

.result p {
  margin: 0;
}

.visually-hidden {
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  height: 1px;
  overflow: hidden;
  position: absolute;
  white-space: nowrap;
  width: 1px;
}

@media (max-width: 30rem) {
  .quiz-shell {
    width: min(100% - 1rem, 50rem);
    padding-top: 1rem;
  }

  .page-header,
  .question,
  .result {
    padding: 1rem;
  }
}

