const form = document.querySelector('#quiz-form');
const scoreElement = document.querySelector('[data-testid="quiz-score"]');
const messageElement = document.querySelector('#form-message');

const correctAnswers = Object.freeze({
  'question-1': 'mars',
  'question-2': 'pacific',
  'question-3': 'six'
});

function getSelectedAnswer(questionName) {
  const selected = form.querySelector(`input[name="${questionName}"]:checked`);
  return selected ? selected.value : null;
}

function getMissingQuestions() {
  return Object.keys(correctAnswers).filter((questionName) => !getSelectedAnswer(questionName));
}

function showValidationMessage(missingQuestions) {
  if (missingQuestions.length === 0) {
    messageElement.hidden = true;
    messageElement.textContent = '';
    return;
  }

  const questionLabels = missingQuestions.map((name) => name.replace('question-', 'Question '));
  messageElement.textContent = `Please answer ${questionLabels.join(' and ')} before submitting.`;
  messageElement.hidden = false;
}

function calculateScore() {
  return Object.entries(correctAnswers).reduce((score, [questionName, answer]) => {
    return score + (getSelectedAnswer(questionName) === answer ? 1 : 0);
  }, 0);
}

function displayScore(score) {
  scoreElement.dataset.score = String(score);
  scoreElement.textContent = `${score} out of 3`;
}

function handleSubmit(event) {
  event.preventDefault();
  const missingQuestions = getMissingQuestions();
  showValidationMessage(missingQuestions);

  if (missingQuestions.length > 0) {
    const firstMissing = form.querySelector(`input[name="${missingQuestions[0]}"]`);
    if (firstMissing) firstMissing.focus();
    return;
  }

  displayScore(calculateScore());
}

form.addEventListener('submit', handleSubmit);
